// A todo has: id, title, done, createdAt. No due date, no tags, no owner.
const FIELDS = ['id', 'title', 'done', 'createdAt'];
const MAX_IMPORT_BYTES = 1024 * 1024; // policy-security S1

const loaded = store.load();
let todos = loaded.ok ? loaded.todos : [];
// The saved list could not be read: never write to it until the user agrees to replace it with a file. Kept in page memory only.
let loadFailed = !loaded.ok;
let saveFailed = false;
let filter = 'all';

const $ = (sel) => document.querySelector(sel);

const SAVE_FAILED = 'Thay đổi vừa rồi chưa được lưu, có thể vì trình duyệt đã hết chỗ. Hãy sao lưu ra file, rồi xoá bớt việc đã xong.';

function add(title) {
  todos.push({ id: crypto.randomUUID(), title: title.trim(), done: false, createdAt: Date.now() });
  commit();
}

function toggle(id) {
  const t = todos.find((x) => x.id === id);
  if (t) t.done = !t.done;
  commit();
}

function remove(id) {
  todos = todos.filter((x) => x.id !== id);
  commit();
}

function commit() {
  // While the saved list is unreadable, changes stay on screen only (the banner says so).
  if (!loadFailed) {
    if (store.save(todos)) {
      if (saveFailed) showMessage('');
      saveFailed = false;
    } else {
      saveFailed = true;
      showMessage(SAVE_FAILED, true);
    }
  }
  render();
}

function showMessage(text, isError = false) {
  const m = $('#message');
  m.textContent = text;
  m.classList.toggle('error', isError);
  m.hidden = !text;
}

function visible() {
  if (filter === 'open') return todos.filter((t) => !t.done);
  if (filter === 'done') return todos.filter((t) => t.done);
  return todos;
}

function render() {
  const list = $('#list');
  list.innerHTML = '';
  for (const t of visible()) {
    const li = document.createElement('li');
    li.className = t.done ? 'done' : '';
    li.innerHTML = `<label><input type="checkbox" ${t.done ? 'checked' : ''}> <span></span></label><button aria-label="Xoá">×</button>`;
    li.querySelector('span').textContent = t.title;
    li.querySelector('input').onchange = () => toggle(t.id);
    li.querySelector('button').onclick = () => remove(t.id);
    list.append(li);
  }
  const open = todos.filter((t) => !t.done).length;
  $('#count').textContent = `${open} việc chưa xong`;
  $('#load-error').hidden = !loadFailed;
  // An unreadable list is not an empty one: show only the banner.
  $('#empty').hidden = todos.length > 0 || loadFailed;
}

// --- Backup to file (F1) ---

function today() {
  const d = new Date();
  const pad = (n) => String(n).padStart(2, '0');
  return `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())}`;
}

function exportFile() {
  if (todos.length === 0) {
    showMessage('Chưa có việc nào để sao lưu');
    return;
  }
  const data = { version: 1, todos: todos.map((t) => Object.fromEntries(FIELDS.map((f) => [f, t[f]]))) };
  const blob = new Blob([JSON.stringify(data, null, 2)], { type: 'application/json' });
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url;
  a.download = `todo-sao-luu-${today()}.json`;
  a.click();
  setTimeout(() => URL.revokeObjectURL(url), 0);
  if (blob.size > MAX_IMPORT_BYTES) {
    showMessage('File sao lưu đã lưu, nhưng quá lớn nên app không nhập lại được.', true);
  } else {
    showMessage(`Đã sao lưu ${todos.length} việc.`);
  }
}

// --- Import from file (F2, F5 step 6) ---

const isPlainObject = (v) => typeof v === 'object' && v !== null && !Array.isArray(v);
const hasExactKeys = (obj, keys) => Object.keys(obj).length === keys.length && keys.every((k) => Object.hasOwn(obj, k));

// Returns the list of todos, or a reason string. Content is only parsed as data, never run.
function parseBackup(text) {
  let data;
  try {
    data = JSON.parse(text);
  } catch {
    return 'not-backup';
  }
  if (!isPlainObject(data) || !hasExactKeys(data, ['version', 'todos']) || data.version !== 1 || !Array.isArray(data.todos)) {
    return 'not-backup';
  }
  if (data.todos.length === 0) return 'empty';
  const ids = new Set();
  for (const t of data.todos) {
    if (!isPlainObject(t) || !hasExactKeys(t, FIELDS)) return 'not-backup';
    if (typeof t.id !== 'string' || typeof t.title !== 'string' || typeof t.done !== 'boolean') return 'not-backup';
    if (typeof t.createdAt !== 'number' || !Number.isFinite(t.createdAt)) return 'damaged';
    if (t.id === '' || ids.has(t.id) || t.title.trim() === '') return 'damaged';
    ids.add(t.id);
  }
  return data.todos.map((t) => ({ id: t.id, title: t.title, done: t.done, createdAt: t.createdAt }));
}

const KEEP = 'Danh sách của bạn vẫn giữ nguyên.';
const REJECTED = {
  'too-big': `File này quá lớn (hơn 1 MB) nên không nhập được. ${KEEP} Hãy chọn một file sao lưu khác.`,
  'unreadable': `Không đọc được file này. ${KEEP} Hãy thử lại, hoặc chọn một file sao lưu khác.`,
  'not-backup': `File này không phải file sao lưu của app nên không nhập được. ${KEEP} Hãy chọn file "todo-sao-luu-…" do app tạo ra.`,
  'damaged': `File sao lưu này bị lỗi (có việc trùng nhau, thiếu tiêu đề hoặc sai ngày tạo) nên không nhập được. ${KEEP} Hãy chọn một file sao lưu khác.`,
  'empty': `File sao lưu này không có việc nào nên không nhập. ${KEEP}`,
};

function confirmText(count) {
  if (loadFailed && todos.length === 0) return `Thay danh sách đã lưu không đọc được bằng ${count} việc trong file?`;
  if (loadFailed) return `Thay danh sách đã lưu không đọc được và ${todos.length} việc bạn vừa thêm (chưa lưu) bằng ${count} việc trong file?`;
  if (todos.length > 0) return `Thay ${todos.length} việc hiện có bằng ${count} việc trong file?`;
  return null; // empty list: nothing is lost, no confirmation (policy-security S2)
}

function askConfirm(text) {
  const dialog = $('#confirm');
  $('#confirm-text').textContent = text;
  dialog.returnValue = '';
