const fs = require('fs');
const vm = require('vm');
const path = require('path');
const APP = process.argv[2];
const src = (f) => fs.readFileSync(path.join(APP, f), 'utf8');

let failures = 0;
const ok = (cond, name) => { console.log(`${cond ? 'PASS' : 'FAIL'}  ${name}`); if (!cond) failures++; };

function el(id) {
  return {
    id, hidden: id === 'load-error' || id === 'message' || id === 'empty', textContent: '', innerHTML: '', value: '', returnValue: '',
    children: [], classList: { set: new Set(), toggle(c, on) { on ? this.set.add(c) : this.set.delete(c); } },
    append(c) { this.children.push(c); }, querySelector() { return el('x'); },
    _listeners: {}, addEventListener(t, f) { this._listeners[t] = f; },
    showModal() { this.open = true; env.dialogShown.push(env.els['confirm-text'].textContent); setTimeout(() => { this.returnValue = env.answer; this._listeners.close(); }, 0); },
    click() { if (this.download !== undefined) env.downloads.push({ name: this.download, url: this.href }); },
  };
}

let env;
function boot(storage, { throwOnGet = false, quota = Infinity } = {}) {
  env = { els: {}, downloads: [], dialogShown: [], answer: 'ok', blobs: {} };
  const ids = ['load-error', 'message', 'add', 'title', 'filters', 'empty', 'list', 'count', 'export', 'import', 'import-file', 'confirm', 'confirm-text'];
  for (const i of ids) env.els[i] = el(i);
  const localStorage = {
    data: storage,
    getItem(k) { if (throwOnGet) throw new Error('denied'); return Object.hasOwn(this.data, k) ? this.data[k] : null; },
    setItem(k, v) { if (String(v).length > quota) throw new Error('QuotaExceededError'); this.data[k] = String(v); },
  };
  let n = 0;
  const ctx = {
    localStorage, console: { error() {} }, crypto: { randomUUID: () => `id-${++n}` }, Date, setTimeout, JSON, Object, Number, String, Set, Array, Promise,
    Blob: class { constructor(parts) { this.text = parts.join(''); this.size = Buffer.byteLength(this.text); } },
    URL: { createObjectURL(b) { const u = `blob:${Object.keys(env.blobs).length}`; env.blobs[u] = b; return u; }, revokeObjectURL() {} },
    document: { querySelector: (s) => env.els[s.slice(1)], querySelectorAll: () => [], createElement: (t) => { const e = el(t); if (t === 'a') e.download = ''; return e; } },
  };
  vm.createContext(ctx);
  vm.runInContext(src('store.js') + '\n' + src('app.js') + '\n;globalThis.__app = { get todos() { return todos; }, add, toggle, remove, importFile };', ctx);
  return { ls: localStorage, app: ctx.__app, $: env.els };
}
