const backup = (n, prefix = 'f') => ({ version: 1, todos: Array.from({ length: n }, (_, i) => ({ id: `${prefix}${i}`, title: `Việc ${prefix}${i}`, done: false, createdAt: 1 })) });
const seed = (n) => ({ 'todo.v1': JSON.stringify(backup(n, 's').todos) });
const lastFile = () => JSON.parse(env.blobs[env.downloads.at(-1).url].text);
const BANNER = 'Không đọc được danh sách đã lưu trên trình duyệt này. Việc bạn thêm hoặc sửa lúc này sẽ không được lưu. Nếu có file sao lưu, hãy bấm "Nhập từ file".';

(async () => {
  const html = src('index.html');
  ok(html.includes(BANNER), 'F5 banner wording verbatim');

  // AC1
  let b = boot({}); b.app.add('A'); b.app.add('B'); b.app.add('C'); b.app.toggle('id-1');
  env.els.export.onclick();
  const d = new Date(); const day = `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`;
  ok(env.downloads[0]?.name === `todo-sao-luu-${day}.json`, 'AC1 file name');
  const f1 = lastFile(); const raw1 = env.blobs[env.downloads[0].url].text;
